import { readFile } from "node:fs/promises";
/** Frozen plugin binaries used to test the SDK host contract. */
export async function loadTestPluginArchives(api = "v2") {
    return await Promise.all(["plugin_csv", "plugin_markdown"].map(async (key) => ({
        key,
        fileName: `${key}.lixplugin`,
        archiveBytes: new Uint8Array(await readFile(new URL(`../../lix/tests/fixtures/plugin-api/${api}/${key}.lixplugin`, import.meta.url))),
    })));
}
